package com.example

/**
 * High-quality, 100% curriculum-accurate Question Bank for Mathematics (ගණිතය)
 * Covers 10 distinct syllabus topics with 10 unique MCQs per set (100 total distinct questions).
 */
object QuizBankMath {

  fun getQuestion(
    grade: String,
    setIdx: Int,
    qIdx: Int,
    qNumber: Int,
    topic: String
  ): QuizQuestion {
    return when (setIdx) {
      // SET 1: සංඛ්‍යා රටා හා ප්‍රථමක සංඛ්‍යා
      1 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "පහත සංඛ්‍යා අතුරින් ප්‍රථමක සංඛ්‍යාවක් (Prime number) වන්නේ කුමක්ද?", listOf("9", "15", "19", "21"), 2, "19 ට ඇත්තේ 1 සහ 19 යන සාධක දෙක පමණක් බැවින් එය ප්‍රථමක සංඛ්‍යාවකි.")
        2 -> QuizQuestion(qNumber, "කුඩාම ඉරට්ටේ ප්‍රථමක සංඛ්‍යාව කුමක්ද?", listOf("0", "1", "2", "4"), 2, "2 යනු ලොව ඇති එකම ඉරට්ටේ ප්‍රථමක සංඛ්‍යාව වේ.")
        3 -> QuizQuestion(qNumber, "3, 7, 11, 15, ... සංඛ්‍යා රටාවේ මීළඟ (5 වන) පදය කුමක්ද?", listOf("17", "18", "19", "20"), 2, "පොදු අන්තරය 4 කි. 15 + 4 = 19.")
        4 -> QuizQuestion(qNumber, "1, 4, 9, 16, 25, ... යනු කුමන ආකාරයේ සංඛ්‍යා රටාවක්ද?", listOf("සමචතුරස්‍ර සංඛ්‍යා", "ත්‍රිකෝණ සංඛ්‍යා", "ප්‍රථමක සංඛ්‍යා", "ඝන සංඛ්‍යා"), 0, "n² (1², 2², 3², 4², 5²) සමචතුරස්‍ර සංඛ්‍යා රටාවයි.")
        5 -> QuizQuestion(qNumber, "4 වන ත්‍රිකෝණ සංඛ්‍යාව කුමක්ද?", listOf("6", "8", "10", "12"), 2, "ත්‍රිකෝණ සංඛ්‍යා සූත්‍රය n(n+1)/2 අනුව, 4 × 5 / 2 = 10.")
        6 -> QuizQuestion(qNumber, "60 හි ප්‍රථමක සාධක ගුණිතයක් ලෙස නිවැරදිව දැක්වෙන්නේ කුමක්ද?", listOf("2 × 3 × 10", "2² × 3 × 5", "4 × 15", "6 × 10"), 1, "60 = 4 × 3 × 5 = 2² × 3 × 5 (සියල්ල ප්‍රථමක වේ).")
        7 -> QuizQuestion(qNumber, "12 සහ 18 යන සංඛ්‍යාවල මහ පොදු සාධකය (ම.පො.සා.) කීයද?", listOf("3", "6", "12", "36"), 1, "12 සහ 18 දෙකම බෙදිය හැකි විශාලතම පොදු සංඛ්‍යාව 6 වේ.")
        8 -> QuizQuestion(qNumber, "4 සහ 6 යන සංඛ්‍යාවල කුඩා පොදු ගුණාකාරය (කු.පො.ගු.) කීයද?", listOf("12", "24", "18", "2"), 0, "4 හි ගුණාකාර (4, 8, 12..) සහ 6 හි ගුණාකාර (6, 12..) අතුරින් කුඩාම පොදු අගය 12 යි.")
        9 -> QuizQuestion(qNumber, "පොදු පදය Tn = 3n - 1 වන සංඛ්‍යා රටාවේ 8 වන පදය කීයද?", listOf("22", "23", "24", "25"), 1, "T₈ = (3 × 8) - 1 = 24 - 1 = 23.")
        else -> QuizQuestion(qNumber, "1 සිට 20 දක්වා ඇති සංඛ්‍යා අතර ඇති ප්‍රථමක සංඛ්‍යා ගණන කීයද?", listOf("6", "7", "8", "9"), 2, "{2, 3, 5, 7, 11, 13, 17, 19} යනුවෙන් ප්‍රථමක සංඛ්‍යා 8ක් ඇත.")
      }

      // SET 2: භාග, දශම හා ප්‍රතිශත
      2 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "2/5 ප්‍රතිශතයක් (Percentage) ලෙස දැක්වූ විට කොපමණද?", listOf("20%", "25%", "40%", "50%"), 2, "2/5 × 100% = 40%.")
        2 -> QuizQuestion(qNumber, "1/3 + 1/6 හි අගය සරල කළ විට ලැබෙන්නේ කුමක්ද?", listOf("2/9", "1/2", "2/6", "3/6"), 1, "2/6 + 1/6 = 3/6 = 1/2.")
        3 -> QuizQuestion(qNumber, "0.75 භාගයක් ලෙස සරලතම ආකාරයෙන් දැක්වූ විට කුමක්ද?", listOf("1/2", "3/4", "7/10", "4/5"), 1, "0.75 = 75/100 = 3/4.")
        4 -> QuizQuestion(qNumber, "500 න් 15% ක අගය කීයද?", listOf("50", "75", "100", "150"), 1, "500 × 15/100 = 75.")
        5 -> QuizQuestion(qNumber, "රු. 800 කට ගත් භාණ්ඩයක් රු. 1000 කට විකුණූ විට ලැබෙන ලාභ ප්‍රතිශතය කීයද?", listOf("20%", "25%", "15%", "30%"), 1, "ලාභය = 200. ප්‍රතිශතය = (200 / 800) × 100% = 25%.")
        6 -> QuizQuestion(qNumber, "3/4 ÷ 1/2 ගණනය කළ විට ලැබෙන අගය කීයද?", listOf("3/8", "1 1/2 (3/2)", "2/3", "1"), 1, "3/4 × 2/1 = 6/4 = 3/2 = 1 1/2.")
        7 -> QuizQuestion(qNumber, "2.4 × 0.5 හි අගය කීයද?", listOf("1.2", "12", "0.12", "1.25"), 0, "2.4 × 0.5 = 1.2.")
        8 -> QuizQuestion(qNumber, "පොතක මුළු පිටු ගණනින් 2/3 ක් කියවූ පසු තව පිටු 40ක් ඉතිරිව තිබේ නම් මුළු පිටු ගණන කීයද?", listOf("80", "120", "100", "60"), 1, "ඉතිරි 1/3 = 40 නම්, මුළු පිටු ගණන = 40 × 3 = 120.")
        9 -> QuizQuestion(qNumber, "12% ක වැට් බද්දක් සහිතව රු. 5000 ක භාණ්ඩයකට ගෙවිය යුතු මුළු මුදල කීයද?", listOf("රු. 5500", "රු. 5600", "රු. 6000", "රු. 5120"), 1, "බද්ද = 5000 × 12/100 = 600. මුළු මුදල = 5000 + 600 = රු. 5600.")
        else -> QuizQuestion(qNumber, "5/8 සහ 3/4 සංසන්දනය කළ විට විශාල භාගය කුමක්ද?", listOf("5/8", "3/4 (6/8)", "දෙකම සමානයි", "කිසිවක් නොවේ"), 1, "3/4 = 6/8 වන අතර එය 5/8 ට වඩා විශාලය.")
      }

      // SET 3: වීජීය ප්‍රකාශන හා සාධක
      3 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "(x + 4)(x - 4) ප්‍රසාරණය කළ විට ලැබෙන්නේ කුමක්ද?", listOf("x² - 8", "x² - 16", "x² + 16", "x² - 4x + 16"), 1, "වර්ග දෙකක අන්තරය: (a+b)(a-b) = a² - b² අනුව x² - 16 ලැබේ.")
        2 -> QuizQuestion(qNumber, "x² - 9 හි සාධක මොනවාද?", listOf("(x - 3)²", "(x - 3)(x + 3)", "(x - 9)(x + 1)", "සාධක නැත"), 1, "x² - 3² = (x - 3)(x + 3).")
        3 -> QuizQuestion(qNumber, "2a(3a + 5b) ප්‍රසාරණය කළ විට ලැබෙන ප්‍රතිඵලය කුමක්ද?", listOf("6a² + 10ab", "5a² + 7ab", "6a + 10b", "6a² + 5ab"), 0, "2a × 3a = 6a² සහ 2a × 5b = 10ab.")
        4 -> QuizQuestion(qNumber, "x² + 5x + 6 හි සාධක මොනවාද?", listOf("(x + 1)(x + 6)", "(x + 2)(x + 3)", "(x - 2)(x - 3)", "(x + 5)(x + 1)"), 1, "ගුණිතය 6 ද එකතුව 5 ද වන සංඛ්‍යා 2 සහ 3 වේ. එනම් (x + 2)(x + 3).")
        5 -> QuizQuestion(qNumber, "3x + 12 ප්‍රකාශනයේ පොදු සාධකය එළියට ගත් විට කුමක්ද?", listOf("3(x + 4)", "3(x + 12)", "x(3 + 12)", "4(x + 3)"), 0, "පොදු සාධකය 3 වේ. 3(x + 4).")
        6 -> QuizQuestion(qNumber, "x = 3 සහ y = -2 නම් 2x - 3y හි අගය කීයද?", listOf("0", "12", "-12", "6"), 1, "2(3) - 3(-2) = 6 - (-6) = 6 + 6 = 12.")
        7 -> QuizQuestion(qNumber, "(a + b)² හි නිවැරදි ප්‍රසාරණය කුමක්ද?", listOf("a² + b²", "a² + 2ab + b²", "a² - 2ab + b²", "2a + 2b"), 1, "පූර්ණ වර්ග ප්‍රසාරණය: a² + 2ab + b².")
        8 -> QuizQuestion(qNumber, "2x² - 8 ප්‍රකාශනයේ සම්පූර්ණ සාධක මොනවාද?", listOf("2(x - 2)(x + 2)", "(2x - 4)(x + 2)", "2(x² - 8)", "(x - 2)"), 0, "2(x² - 4) = 2(x - 2)(x + 2).")
        9 -> QuizQuestion(qNumber, "x² - 6x + 9 පූර්ණ වර්ගයක් ලෙස ලියූ විට කුමක්ද?", listOf("(x + 3)²", "(x - 3)²", "(x - 9)²", "(x + 9)²"), 1, "x² - 2(3)x + 3² = (x - 3)².")
        else -> QuizQuestion(qNumber, "ax + ay + bx + by සාධක වෙන් කළ විට කුමක්ද?", listOf("(a + b)(x + y)", "(a + x)(b + y)", "ab(x + y)", "(x - y)(a - b)"), 0, "a(x + y) + b(x + y) = (a + b)(x + y).")
      }

      // SET 4: සරල හා යුගලත් සමීකරණ
      4 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "3x - 7 = 14 සමීකරණයේ x හි අගය කීයද?", listOf("5", "7", "9", "21"), 1, "3x = 14 + 7 = 21 => x = 7.")
        2 -> QuizQuestion(qNumber, "x/4 + 2 = 5 සමීකරණයේ x හි අගය කුමක්ද?", listOf("8", "12", "16", "20"), 1, "x/4 = 3 => x = 3 × 4 = 12.")
        3 -> QuizQuestion(qNumber, "2(x + 3) = 16 නම් x කීයද?", listOf("4", "5", "6", "8"), 1, "x + 3 = 8 => x = 5.")
        4 -> QuizQuestion(qNumber, "x + y = 10 සහ x - y = 4 නම් x හි අගය කීයද?", listOf("5", "6", "7", "8"), 2, "සමීකරණ දෙක එකතු කළ විට 2x = 14 => x = 7.")
        5 -> QuizQuestion(qNumber, "ඉහත සමීකරණ යුගලයේ y හි අගය කීයද?", listOf("2", "3", "4", "5"), 1, "7 + y = 10 => y = 3.")
        6 -> QuizQuestion(qNumber, "5x + 3 = 2x + 18 නම් x හි අගය කීයද?", listOf("3", "5", "7", "9"), 1, "5x - 2x = 18 - 3 => 3x = 15 => x = 5.")
        7 -> QuizQuestion(qNumber, "සංඛ්‍යාවක තුන් ගුණයෙන් 5ක් අඩු කළ විට 16 ලැබේ නම් එම සංඛ්‍යාව කීයද?", listOf("5", "7", "9", "11"), 1, "3x - 5 = 16 => 3x = 21 => x = 7.")
        8 -> QuizQuestion(qNumber, "2x + 3y = 12 සහ y = 2 නම් x හි අගය කීයද?", listOf("2", "3", "4", "6"), 1, "2x + 3(2) = 12 => 2x + 6 = 12 => 2x = 6 => x = 3.")
        9 -> QuizQuestion(qNumber, "පියාගේ වයස පුතාගේ වයස මෙන් 3 ගුණයකි. දෙදෙනාගේ වයස් එකතුව 48 නම් පුතාගේ වයස කීයද?", listOf("10", "12", "14", "16"), 1, "x + 3x = 48 => 4x = 48 => x = 12.")
        else -> QuizQuestion(qNumber, "(x - 2)/3 = 4 සමීකරණයේ විසඳුම කුමක්ද?", listOf("10", "12", "14", "16"), 2, "x - 2 = 12 => x = 14.")
      }

      // SET 5: පයිතගරස් ප්‍රමේයය හා ත්‍රිකෝණ
      5 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "ඍජුකෝණී ත්‍රිකෝණයක ආසන්න පාද 6 cm හා 8 cm නම් කර්ණයේ දිග කීයද?", listOf("10 cm", "12 cm", "14 cm", "100 cm"), 0, "c² = 6² + 8² = 36 + 64 = 100 => c = 10 cm.")
        2 -> QuizQuestion(qNumber, "කර්ණය 13 cm ද එක් පාදයක් 5 cm ද වන ඍජුකෝණී ත්‍රිකෝණයේ අනෙක් පාදය කීයද?", listOf("8 cm", "10 cm", "12 cm", "15 cm"), 2, "b² = 13² - 5² = 169 - 25 = 144 => b = 12 cm.")
        3 -> QuizQuestion(qNumber, "ත්‍රිකෝණයක අභ්‍යන්තර කෝණ තුනෙහි එකතුව අංශක කීයද?", listOf("90°", "180°", "270°", "360°"), 1, "ඕනෑම තලීය ත්‍රිකෝණයක අභ්‍යන්තර කෝණ එකතුව 180° කි.")
        4 -> QuizQuestion(qNumber, "සමපාද ත්‍රිකෝණයක එක් කෝණයක අගය අංශක කීයද?", listOf("45°", "60°", "90°", "120°"), 1, "සමපාද ත්‍රිකෝණයක කෝණ 3ම සමාන වේ: 180° / 3 = 60°.")
        5 -> QuizQuestion(qNumber, "සමද්වීපාද ත්‍රිකෝණයක ශීර්ෂ කෝණය 80° නම් සමාන පාද ඉදිරියෙන් ඇති කෝණ කීයද?", listOf("40° බැගින්", "50° බැගින්", "60° බැගින්", "45° බැගින්"), 1, "(180° - 80°) / 2 = 100° / 2 = 50°.")
        6 -> QuizQuestion(qNumber, "ත්‍රිකෝණමිතියේ Tanθ අර්ථ දැක්වෙන්නේ කෙසේද?", listOf("සම්මුඛ පාදය / කර්ණය", "බද්ධ පාදය / කර්ණය", "සම්මුඛ පාදය / බද්ධ පාදය", "කර්ණය / සම්මුඛ පාදය"), 2, "Tanθ = Opposite / Adjacent (සම්මුඛ පාදය / බද්ධ පාදය).")
        7 -> QuizQuestion(qNumber, "Sin 30° හි අගය කීයද?", listOf("0", "1/2 (0.5)", "√3/2", "1"), 1, "සම්මත ත්‍රිකෝණමිතික අගය: Sin 30° = 1/2.")
        8 -> QuizQuestion(qNumber, "පාද 3ක් දී ඇති විට ඍජුකෝණී ත්‍රිකෝණයක් සාදන ත්‍රිත්වය කුමක්ද?", listOf("2, 3, 4", "3, 4, 5", "4, 5, 6", "5, 6, 7"), 1, "3² + 4² = 9 + 16 = 25 = 5² බැවින් පයිතගරස් ත්‍රිත්වයකි.")
        9 -> QuizQuestion(qNumber, "ආධාරක පාදය 10 cm ද ලම්බ උස 6 cm ද වන ත්‍රිකෝණයක වර්ගඵලය කීයද?", listOf("60 cm²", "30 cm²", "16 cm²", "15 cm²"), 1, "වර්ගඵලය = ½ × ආධාරකය × උස = ½ × 10 × 6 = 30 cm².")
        else -> QuizQuestion(qNumber, "ත්‍රිකෝණයක එක් පාදයක් දික් කළ විට සෑදෙන බාහිර කෝණය සමාන වන්නේ කුමකටද?", listOf("බද්ධ කෝණයට", "අභ්‍යන්තර සම්මුඛ කෝණ දෙකේ එකතුවට", "180° කට", "90° කට"), 1, "බාහිර කෝණ ප්‍රමේයය: ත්‍රිකෝණයක බාහිර කෝණය අභ්‍යන්තර සම්මුඛ කෝණ දෙකේ එකතුවට සමාන වේ.")
      }

      // SET 6: වෘත්ත ප්‍රමේය හා ජ්‍යාමිතිය
      6 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "වෘත්තයක කේන්ද්‍රයේ සිට ජ්‍යායකට අඳින ලද ලම්භය මඟින් ජ්‍යායට කුමක් කරයිද?", listOf("ජ්‍යාය දෙගුණ කරයි", "ජ්‍යාය සමච්ඡේදනය කරයි (සමාන කොටස් දෙකකට බෙදයි)", "ජ්‍යාය අක්‍රිය කරයි", "වෙනසක් නැත"), 1, "කේන්ද්‍රයේ සිට ජ්‍යායකට අඳින ලම්බය මඟින් එම ජ්‍යාය සමච්ඡේදනය වේ.")
        2 -> QuizQuestion(qNumber, "වෘත්තයක අර්ධ වෘත්තාකාර ඛණ්ඩයක පිහිටි කෝණය කුමක්ද?", listOf("සුළු කෝණයකි", "ඍජුකෝණයකි (90°)", "මහා කෝණයකි", "සරල කෝණයකි"), 1, "අර්ධ වෘත්තයේ කෝණය සෑමවිටම ඍජුකෝණයක් (90°) වේ.")
        3 -> QuizQuestion(qNumber, "චක්‍රීය චතුරස්‍රයක සම්මුඛ කෝණ දෙකක ඓක්‍යය අංශක කීයද?", listOf("90°", "180° (පරිපූරක වේ)", "270°", "360°"), 1, "චක්‍රීය චතුරස්‍ර ප්‍රමේයය අනුව සම්මුඛ කෝණ පරිපූරක වේ (එකතුව 180°).")
        4 -> QuizQuestion(qNumber, "වෘත්ත චාපයකින් කේන්ද්‍රයෙහි ආපාතනය කරන කෝණය, පරිධිය මත ආපාතනය කරන කෝණය මෙන් කී ගුණයක්ද?", listOf("සමාන වේ", "දෙගුණයකි (2x)", "තුන්ගුණයකි", "අඩකි"), 1, "කේන්ද්‍ර කෝණය පරිධි කෝණය මෙන් දෙගුණයක් වේ.")
        5 -> QuizQuestion(qNumber, "එකම වෘත්ත ඛණ්ඩයේ පිහිටි කෝණ පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?", listOf("එකිනෙකට වෙනස් වේ", "එකිනෙකට සමාන වේ", "එකතුව 180° කි", "එකතුව 90° කි"), 1, "එකම වෘත්ත චාපය මඟින් එකම වෘත්ත ඛණ්ඩයේ සාදන සියලු පරිධි කෝණ සමාන වේ.")
        6 -> QuizQuestion(qNumber, "වෘත්තයකට ස්පර්ශකයක් අඳින ලක්ෂ්‍යයේදී ස්පර්ශකය හා අරය අතර කෝණය කීයද?", listOf("45°", "60°", "90° (ඍජුකෝණී)", "180°"), 2, "ස්පර්ශ ලක්ෂ්‍යයේදී අරය සහ ස්පර්ශකය එකිනෙකට ලම්බක වේ.")
        7 -> QuizQuestion(qNumber, "වෘත්තයකින් පිටත ලක්ෂ්‍යයක සිට එම වෘත්තයට ඇඳිය හැකි ස්පර්ශක සංඛ්‍යාව කීයද?", listOf("1 කි", "2 කි", "3 කි", "අනන්තයකි"), 1, "බාහිර ලක්ෂ්‍යයක සිට වෘත්තයකට හරියටම සමාන දිගැති ස්පර්ශක 2ක් ඇඳිය හැක.")
        8 -> QuizQuestion(qNumber, "චක්‍රීය චතුරස්‍රයක එක් කෝණයක් 110° නම් ඊට සම්මුඛ කෝණය කීයද?", listOf("70°", "80°", "90°", "110°"), 0, "180° - 110° = 70°.")
        9 -> QuizQuestion(qNumber, "කේන්ද්‍ර කෝණය 80° නම් එම චාපයෙන්ම පරිධිය මත සාදන කෝණය කීයද?", listOf("160°", "80°", "40°", "20°"), 2, "පරිධි කෝණය = කේන්ද්‍ර කෝණයෙන් අඩක් = 80° / 2 = 40°.")
        else -> QuizQuestion(qNumber, "කෝණයක කෝණ සමච්ඡේදකය මත පිහිටි ඕනෑම ලක්ෂ්‍යයක් කෝණයේ බාහුවලට කෙසේ පිහිටයිද?", listOf("සමදුරින් පිහිටයි", "අසමාන දුරින්", "ලම්බක නොවේ", "දුර මැනිය නොහැක"), 0, "කෝණ සමච්ඡේදකයේ ලක්ෂ්‍ය කෝණයේ බාහු දෙකට සමදුරින් පිහිටයි.")
      }

      // SET 7: ක්ෂේත්‍රඵලය හා පරිමාව ගණනය
      7 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "අරය 7 cm වන වෘත්තයක වර්ගඵලය කොපමණද? (π = 22/7)", listOf("44 cm²", "88 cm²", "154 cm²", "308 cm²"), 2, "A = πr² = (22/7) × 7 × 7 = 154 cm².")
        2 -> QuizQuestion(qNumber, "දිග 8 cm, පළල 5 cm සහ උස 4 cm වන ඝනකාභයක පරිමාව කීයද?", listOf("80 cm³", "160 cm³", "17 cm³", "40 cm³"), 1, "V = l × b × h = 8 × 5 × 4 = 160 cm³.")
        3 -> QuizQuestion(qNumber, "පැත්තක දිග 5 cm වන ඝනකයක පරිමාව කොපමණද?", listOf("25 cm³", "100 cm³", "125 cm³", "150 cm³"), 2, "V = a³ = 5 × 5 × 5 = 125 cm³.")
        4 -> QuizQuestion(qNumber, "අරය r සහ උස h වන සිලින්ඩරයක පරිමාව සෙවීමේ සූත්‍රය කුමක්ද?", listOf("2πrh", "πr²h", "⅓πr²h", "4/3πr³"), 1, "සිලින්ඩරයක පරිමාව = හරස්කඩ වර්ගඵලය × උස = πr²h.")
        5 -> QuizQuestion(qNumber, "සමාන්තර පාද 6 cm හා 10 cm ද ලම්බ උස 4 cm ද වන ත්‍රපීසියමක වර්ගඵලය කීයද?", listOf("64 cm²", "32 cm²", "40 cm²", "24 cm²"), 1, "A = ½(a + b)h = ½(6 + 10) × 4 = ½(16) × 4 = 32 cm².")
        6 -> QuizQuestion(qNumber, "අරය 7 cm වන අර්ධ වෘත්තාකාර තහඩුවක වට ප්‍රමාණය (පරිමිතිය) කීයද?", listOf("22 cm", "36 cm (22 + 14)", "44 cm", "154 cm"), 1, "චාප දිග πr = 22 cm, විෂ්කම්භය 2r = 14 cm. මුළු පරිමිතිය = 22 + 14 = 36 cm.")
        7 -> QuizQuestion(qNumber, "පැත්ත 6 cm වන ඝනකයක මුළු පෘෂ්ඨ වර්ගඵලය කීයද?", listOf("36 cm²", "144 cm²", "216 cm²", "180 cm²"), 2, "මුහුණත් 6කි. මුළු වර්ගඵලය = 6 × (6 × 6) = 6 × 36 = 216 cm².")
        8 -> QuizQuestion(qNumber, "කේන්ද්‍රික ඛණ්ඩයක කෝණය 90° (කාල් වෘත්තයක්) සහ අරය 7 cm නම් වර්ගඵලය කීයද?", listOf("38.5 cm²", "77 cm²", "154 cm²", "22 cm²"), 0, "A = (90/360) × πr² = ¼ × 154 = 38.5 cm².")
        9 -> QuizQuestion(qNumber, "වෘත්තාකාර කේතුවක පරිමාව, සමාන අරය හා උස ඇති සිලින්ඩරයක පරිමාව මෙන් කොපමණද?", listOf("සමාන වේ", "⅓ කි (තුනෙන් එකකි)", "½ කි", "¼ කි"), 1, "කේතුවේ පරිමාව V = ⅓πr²h වේ.")
        else -> QuizQuestion(qNumber, "අරය 7 cm වන සිලින්ඩරයක උස 10 cm නම් එහි වක්‍ර පෘෂ්ඨ වර්ගඵලය කීයද? (2πrh)", listOf("220 cm²", "440 cm²", "1540 cm²", "880 cm²"), 1, "A = 2 × (22/7) × 7 × 10 = 440 cm².")
      }

      // SET 8: සමාන්තර හා ගුණෝත්තර ශ්‍රේඪි
      8 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "5, 9, 13, 17, ... සමාන්තර ශ්‍රේඪියේ පොදු අන්තරය (d) කීයද?", listOf("2", "3", "4", "5"), 2, "d = T₂ - T₁ = 9 - 5 = 4.")
        2 -> QuizQuestion(qNumber, "මුල් පදය a = 3 සහ පොදු අන්තරය d = 5 වන සමාන්තර ශ්‍රේඪියේ 10 වන පදය (T₁₀) කීයද?", listOf("45", "48", "50", "53"), 1, "T₁₀ = a + (10 - 1)d = 3 + (9 × 5) = 3 + 45 = 48.")
        3 -> QuizQuestion(qNumber, "2, 6, 18, 54, ... යනු කුමන ආකාරයේ ශ්‍රේඪියක්ද?", listOf("සමාන්තර ශ්‍රේඪියක්", "ගුණෝත්තර ශ්‍රේඪියක් (Geometric Progression)", "සංඛ්‍යා රටාවක් නොවේ", "අපසාරී"), 1, "සෑම පදයක්ම 3න් ගුණවීමෙන් සෑදෙන බැවින් පොදු අනුපාතය r = 3 වූ ගුණෝත්තර ශ්‍රේඪියකි.")
        4 -> QuizQuestion(qNumber, "ඉහත ගුණෝත්තර ශ්‍රේඪියේ පොදු අනුපාතය (r) කීයද?", listOf("2", "3", "4", "6"), 1, "r = T₂ / T₁ = 6 / 2 = 3.")
        5 -> QuizQuestion(qNumber, "සමාන්තර ශ්‍රේඪියක මුල් පද n හි එකතුව (Sn) සෙවීමේ සූත්‍රය කුමක්ද?", listOf("Sn = n/2 [2a + (n-1)d]", "Sn = a + (n-1)d", "Sn = n(a + d)", "Sn = a rⁿ"), 0, "සමාන්තර ශ්‍රේඪි ඓක්‍ය සූත්‍රය: Sn = n/2 [2a + (n-1)d] හෝ Sn = n/2 (a + l).")
        6 -> QuizQuestion(qNumber, "1, 2, 3, 4, ... මුල් පද 10 හි එකතුව කීයද?", listOf("45", "50", "55", "60"), 2, "S₁₀ = 10/2 [2(1) + 9(1)] = 5 [11] = 55.")
        7 -> QuizQuestion(qNumber, "ගුණෝත්තර ශ්‍රේඪියක a = 2, r = 2 නම් 5 වන පදය (T₅) කීයද?", listOf("16", "32", "64", "10"), 1, "T₅ = a r⁴ = 2 × 2⁴ = 2 × 16 = 32.")
        8 -> QuizQuestion(qNumber, "සමාන්තර ශ්‍රේඪියක 3 වන පදය 11 ද 7 වන පදය 23 ද නම් පොදු අන්තරය d කීයද?", listOf("2", "3", "4", "5"), 1, "T₇ - T₃ = 4d = 23 - 11 = 12 => d = 3.")
        9 -> QuizQuestion(qNumber, "20, 17, 14, 11, ... ශ්‍රේඪියේ පොදු අන්තරය කුමක්ද?", listOf("3", "-3", "4", "-4"), 1, "d = 17 - 20 = -3.")
        else -> QuizQuestion(qNumber, "ගුණෝත්තර ශ්‍රේඪියක n වන පදය සෙවීමේ සූත්‍රය කුමක්ද?", listOf("Tn = a + (n-1)d", "Tn = a rⁿ⁻¹", "Tn = a rⁿ", "Tn = n a r"), 1, "Tn = a rⁿ⁻¹ (a = මුල් පදය, r = පොදු අනුපාතය).")
      }

      // SET 9: සම්භාවිතාව හා නියැදි අවකාශ
      9 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "සාධාරණ දාදු කැටයක් එක්වරක් උඩ දැමූ විට ලැබිය හැකි මුළු ප්‍රතිඵල ගණන (නියැදි අවකාශය) කීයද?", listOf("4", "6", "8", "12"), 1, "දාදු කැටයක {1, 2, 3, 4, 5, 6} ලෙස මුහුණත් 6කි.")
        2 -> QuizQuestion(qNumber, "සාධාරණ දාදු කැටයක් දැමූ විට 4 ට වඩා වැඩි සංඛ්‍යාවක් ලැබීමේ සම්භාවිතාව කුමක්ද?", listOf("1/6", "2/6 (1/3)", "3/6 (1/2)", "4/6"), 1, "4ට වැඩි සංඛ්‍යා {5, 6} (අවස්ථා 2ක්). සම්භාවිතාව = 2/6 = 1/3.")
        3 -> QuizQuestion(qNumber, "කාසියක් දෙවරක් උඩ දැමූ විට ලැබෙන නියැදි අවකාශයේ මූලද්‍රව්‍ය ගණන කීයද?", listOf("2", "4", "6", "8"), 1, "{HH, HT, TH, TT} වශයෙන් ප්‍රතිඵල 2² = 4ක් ලැබේ.")
        4 -> QuizQuestion(qNumber, "කාසියක් උඩ දැමූ විට හිස (Head) ලැබීමේ සම්භාවිතාව කුමක්ද?", listOf("1/4", "1/2", "3/4", "1"), 1, "හිස හෝ අගය ලැබීමේ සම්භාවිතාව 1/2 කි.")
        5 -> QuizQuestion(qNumber, "සිදුවීමක් ස්ථිරවම සිදුවන්නේ නම් එහි සම්භාවිතාව කුමක්ද?", listOf("0", "0.5", "1", "100"), 2, "ස්ථිර සිදුවීමක සම්භාවිතාව 1 වන අතර අසම්භව්‍ය සිදුවීමක සම්භාවිතාව 0 වේ.")
        6 -> QuizQuestion(qNumber, "රතු බෝල 5ක් සහ නිල් බෝල 3ක් ඇති බෑගයකින් අහඹු ලෙස ගත් බෝලය රතු එකක් වීමේ සම්භාවිතාව කීයද?", listOf("3/8", "5/8", "1/2", "5/3"), 1, "මුළු බෝල 8කි. රතු බෝල 5කි. සම්භාවිතාව = 5/8.")
        7 -> QuizQuestion(qNumber, "සිදුවීමක් සිදුනොවීමේ සම්භාවිතාව P(A') සොයන්නේ කෙසේද?", listOf("1 - P(A)", "1 + P(A)", "P(A) / 2", "0"), 0, "පූරක සම්භාවිතාව: P(A') = 1 - P(A).")
        8 -> QuizQuestion(qNumber, "P(A) = 0.35 නම් P(A') හි අගය කීයද?", listOf("0.35", "0.65", "0.75", "1.35"), 1, "1 - 0.35 = 0.65.")
        9 -> QuizQuestion(qNumber, "පරස්පර විවර්ජිත සිදුවීම් දෙකක ඡේදනය P(A ∩ B) කුමක්ද?", listOf("0", "1", "P(A) × P(B)", "0.5"), 0, "එකවර සිදුවිය නොහැකි සිදුවීම්වල පොදු අවස්ථා නැත (P(A ∩ B) = 0).")
        else -> QuizQuestion(qNumber, "වෘක්ෂ සටහනක (Tree Diagram) එක් ශාඛා ලක්ෂ්‍යයකින් පිටවන සියලු අතුවල සම්භාවිතාවල එකතුව කීයද?", listOf("0", "0.5", "1", "අනන්තය"), 2, "ඕනෑම අවස්ථාවක සියලු විකල්ප සම්භාවිතාවල එකතුව සෑමවිටම 1 ක් වේ.")
      }

      // SET 10: සංඛ්‍යානය හා ප්‍රස්තාර විග්‍රහය
      else -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "3, 5, 7, 9, 11 යන සංඛ්‍යාවල මධ්‍යන්‍යය (සාමාන්‍යය) කීයද?", listOf("5", "7", "9", "35"), 1, "ඓක්‍යය = 35. සංඛ්‍යා ගණන = 5. මධ්‍යන්‍යය = 35 / 5 = 7.")
        2 -> QuizQuestion(qNumber, "2, 4, 4, 5, 7, 8, 9 දත්ත සමූහයේ මාතය (Mode) කුමක්ද?", listOf("2", "4", "5", "7"), 1, "වැඩිම වාර ගණනක් (2 වතාවක්) පුනරාවර්තනය වන අගය 4 වේ.")
        3 -> QuizQuestion(qNumber, "3, 8, 4, 12, 6 දත්තවල මධ්‍යස්ථය (Median) සෙවීමට පළමුව කුමක් කළ යුතුද?", listOf("එකතු කළ යුතුය", "ආරෝහණ පිළිවෙලට සැකසිය යුතුය", "ගුණ කළ යුතුය", "වර්ග කළ යුතුය"), 1, "පිළිවෙලට සැකසූ විට: 3, 4, 6, 8, 12. මැද අගය 6 වේ.")
        4 -> QuizQuestion(qNumber, "දත්ත සමූහයක විශාලතම අගය සහ කුඩාම අගය අතර වෙනස හඳුන්වන්නේ කුමක්ද?", listOf("මාතය", "පරාසය (Range)", "මධ්‍යස්ථය", "සංඛ්‍යාතය"), 1, "පරාසය = උපරිම අගය - අවම අගය.")
        5 -> QuizQuestion(qNumber, "15, 22, 8, 30, 19 දත්තවල පරාසය කීයද?", listOf("15", "22", "8", "22 (30 - 8)"), 3, "පරාසය = 30 - 8 = 22.")
        6 -> QuizQuestion(qNumber, "y = 2x + 3 සරල රේඛාවේ අනුක්‍රමණය (Gradient - m) කීයද?", listOf("2", "3", "5", "-2"), 0, "y = mx + c සමීකරණය අනුව අනුක්‍රමණය m = 2 වේ.")
        7 -> QuizQuestion(qNumber, "ඉහත සරල රේඛාවේ y-අන්තඃඛණ්ඩය (Intercept - c) කීයද?", listOf("2", "3", "0", "1"), 1, "රේඛාව y අක්ෂය ඡේදනය කරන ලක්ෂ්‍යය c = 3 වේ.")
        8 -> QuizQuestion(qNumber, "(1, 2) සහ (3, 6) ලක්ෂ්‍ය යා කරන සරල රේඛාවේ අනුක්‍රමණය කීයද?", listOf("1", "2", "3", "4"), 1, "m = (y₂ - y₁) / (x₂ - x₁) = (6 - 2) / (3 - 1) = 4 / 2 = 2.")
        9 -> QuizQuestion(qNumber, "සමුච්චිත සංඛ්‍යාත වක්‍රයක් (Ogive) භාවිතයෙන් ප්‍රස්ථාරිකව සොයාගත හැකි අගය කුමක්ද?", listOf("මධ්‍යස්ථය (Median)", "මාතය පමණි", "පරාසය පමණි", "අනුක්‍රමණය"), 0, "N/2 පිහිටුමෙන් ප්‍රස්ථාරය ඇසුරෙන් මධ්‍යස්ථය සහ චතුර්ථක නිවැරදිව කියවිය හැක.")
        else -> QuizQuestion(qNumber, "වෘත්ත ප්‍රස්ථාරයක (Pie Chart) මුළු කෝණවල එකතුව අංශක කීයද?", listOf("90°", "180°", "270°", "360°"), 3, "කේන්ද්‍රය වටා සම්පූර්ණ කෝණය 360° ක් වන අතර දත්ත ප්‍රතිශත අනුව බෙදා දක්වයි.")
      }
    }
  }
}
